import express, { type Request, type Response } from 'express'

const PORT = process.env.PORT || 8080

// Define a custom tool
const calculatorTool = strands.tool({
  name: 'calculator',
  description: 'Performs basic arithmetic operations',
  inputSchema: z.object({
    operation: z.enum(['add', 'subtract', 'multiply', 'divide']),
    a: z.number(),
    b: z.number(),
  }),
  callback: (input): number => {
    switch (input.operation) {
      case 'add':
        return input.a + input.b
      case 'subtract':
        return input.a - input.b
      case 'multiply':
        return input.a * input.b
      case 'divide':
        return input.a / input.b
    }
  },
})

// Configure the agent with Amazon Bedrock
const agent = new strands.Agent({
  model: new strands.BedrockModel({
    region: 'ap-southeast-2', // Change to your preferred region
  }),
  tools: [calculatorTool],
})

const app = express()

// Health check endpoint (REQUIRED)
// Omit time_of_last_update: a timestamp that advances on every ping keeps the session alive until maxLifetime.
app.get('/ping', (_, res) => res.json({ status: 'Healthy' }))

// Agent invocation endpoint (REQUIRED)
// AWS sends binary payload, so we use express.raw middleware
app.post('/invocations', express.raw({ type: '*/*' }), async (req, res) => {
  try {
    // Decode binary payload from AWS SDK
    const prompt = new TextDecoder().decode(req.body)

    // Invoke the agent
    const response = await agent.invoke(prompt)

    // Return response
    return res.json({ response })
  } catch (err) {
    console.error('Error processing request:', err)
    return res.status(500).json({ error: 'Internal server error' })
  }
})

// Start server
app.listen(PORT, () => {
  console.log(`🚀 AgentCore Runtime server listening on port ${PORT}`)
  console.log(`📍 Endpoints:`)
  console.log(`   POST http://0.0.0.0:${PORT}/invocations`)
  console.log(`   GET  http://0.0.0.0:${PORT}/ping`)
})

#!/bin/bash

# Script to create IAM role for AWS Bedrock AgentCore Runtime
# Based on the CloudFormation AgentCoreRuntimeExecutionRole

set -e

# Get AWS Account ID and Region
ACCOUNT_ID=$(aws sts get-caller-identity --query Account --output text)
REGION=${AWS_REGION:-ap-southeast-2}

echo "Creating IAM role for Bedrock AgentCore Runtime..."
echo "Account ID: ${ACCOUNT_ID}"
echo "Region: ${REGION}"

# Role name
ROLE_NAME="BedrockAgentCoreRuntimeRole"

# Create trust policy documentf
TRUST_POLICY=$(cat <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "AssumeRolePolicy",
      "Effect": "Allow",
      "Principal": {
        "Service": "bedrock-agentcore.amazonaws.com"
      },
      "Action": "sts:AssumeRole",
      "Condition": {
        "StringEquals": {
          "aws:SourceAccount": "${ACCOUNT_ID}"
        },
        "ArnLike": {
          "aws:SourceArn": "arn:aws:bedrock-agentcore:${REGION}:${ACCOUNT_ID}:*"
        }
      }
    }
  ]
}
EOF
)

# Create permissions policy document
PERMISSIONS_POLICY=$(cat <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "ECRImageAccess",
      "Effect": "Allow",
      "Action": [
        "ecr:BatchGetImage",
        "ecr:GetDownloadUrlForLayer"
      ],
      "Resource": "arn:aws:ecr:${REGION}:${ACCOUNT_ID}:repository/*"
    },
    {
      "Sid": "ECRTokenAccess",
      "Effect": "Allow",
      "Action": "ecr:GetAuthorizationToken",
      "Resource": "*"
    },
    {
      "Effect": "Allow",
      "Action": [
        "logs:DescribeLogStreams",
        "logs:CreateLogGroup"
      ],
      "Resource": "arn:aws:logs:${REGION}:${ACCOUNT_ID}:log-group:/aws/bedrock-agentcore/runtimes/*"
    },
    {
      "Effect": "Allow",
      "Action": "logs:DescribeLogGroups",
      "Resource": "arn:aws:logs:${REGION}:${ACCOUNT_ID}:log-group:*"
    },
    {
      "Effect": "Allow",
      "Action": [
        "logs:CreateLogStream",
        "logs:PutLogEvents"
      ],
      "Resource": "arn:aws:logs:${REGION}:${ACCOUNT_ID}:log-group:/aws/bedrock-agentcore/runtimes/*:log-stream:*"
    },
    {
      "Effect": "Allow",
      "Action": [
        "xray:PutTraceSegments",
        "xray:PutTelemetryRecords",
        "xray:GetSamplingRules",
        "xray:GetSamplingTargets"
      ],
      "Resource": "*"
    },
    {
      "Effect": "Allow",
      "Action": "cloudwatch:PutMetricData",
      "Resource": "*",
      "Condition": {
        "StringEquals": {
          "cloudwatch:namespace": "bedrock-agentcore"
        }
      }
    },
    {
      "Sid": "BedrockModelAccess",
      "Effect": "Allow",
      "Action": [
        "bedrock:InvokeModel",
        "bedrock:InvokeModelWithResponseStream"
      ],
      "Resource": [
        "arn:aws:bedrock:*::foundation-model/*",
        "arn:aws:bedrock:${REGION}:${ACCOUNT_ID}:*"
      ]
    }
  ]
}
EOF
)

# Check if role already exists
if aws iam get-role --role-name ${ROLE_NAME} 2>/dev/null; then
  echo "Role ${ROLE_NAME} already exists."
  echo "Role ARN: $(aws iam get-role --role-name ${ROLE_NAME} --query 'Role.Arn' --output text)"
  exit 0
fi

# Create the IAM role
echo "Creating IAM role: ${ROLE_NAME}"
aws iam create-role \
  --role-name ${ROLE_NAME} \
  --assume-role-policy-document "${TRUST_POLICY}" \
  --description "Service role for AWS Bedrock AgentCore Runtime" \
  --tags Key=ManagedBy,Value=Script Key=Purpose,Value=BedrockAgentCore

echo "Attaching permissions policy to role..."
aws iam put-role-policy \
  --role-name ${ROLE_NAME} \
  --policy-name AgentCoreRuntimeExecutionPolicy \
  --policy-document "${PERMISSIONS_POLICY}"

# Get the role ARN
ROLE_ARN=$(aws iam get-role --role-name ${ROLE_NAME} --query 'Role.Arn' --output text)

echo ""
echo "✅ IAM Role created successfully!"
echo ""
echo "Role Name: ${ROLE_NAME}"
echo "Role ARN:  ${ROLE_ARN}"
echo ""
echo "Use this ARN in your create-agent-runtime command:"
echo "  --role-arn ${ROLE_ARN}"
echo ""
echo "You can also set it as an environment variable:"
echo "  export ROLE_ARN=${ROLE_ARN}"

import { describe, it, expect, vi } from 'vitest'
import { ModelExtractor } from '../model-extractor.js'
import { MockMessageModel } from '../../../__fixtures__/mock-message-model.js'
import { Tracer } from '../../../telemetry/tracer.js'
import type { Model } from '../../../models/model.js'
import type { MessageData } from '../../../types/messages.js'

function userTurn(text: string): MessageData {
  return { role: 'user', content: [{ text }] }
}

describe('ModelExtractor', () => {
  it('parses a JSON array of entries from the model response', async () => {
    const model = new MockMessageModel()
    model.addTurn({
      type: 'textBlock',
      text: '[{"content": "User prefers dark mode"}, {"content": "Lives in Berlin"}]',
    })

    const extractor = new ModelExtractor({ model: model as unknown as Model })
    const entries = await extractor.extract([userTurn('I like dark mode and live in Berlin')])

    expect(entries).toEqual([{ content: 'User prefers dark mode' }, { content: 'Lives in Berlin' }])
  })

  it('extracts a JSON array even when wrapped in prose or a code fence', async () => {
    const model = new MockMessageModel()
    model.addTurn({
      type: 'textBlock',
      text: 'Here are the facts:\n```json\n[{"content": "fact"}]\n```\nHope that helps.',
    })

    const extractor = new ModelExtractor({ model: model as unknown as Model })
    const entries = await extractor.extract([userTurn('something')])

    expect(entries).toEqual([{ content: 'fact' }])
  })

  it('preserves entry metadata', async () => {
    const model = new MockMessageModel()
    model.addTurn({ type: 'textBlock', text: '[{"content": "fact", "metadata": {"topic": "pref"}}]' })

    const extractor = new ModelExtractor({ model: model as unknown as Model })
    const entries = await extractor.extract([userTurn('x')])

    expect(entries).toEqual([{ content: 'fact', metadata: { topic: 'pref' } }])
  })

  it('returns no entries on malformed JSON without throwing', async () => {
    const model = new MockMessageModel()
    model.addTurn({ type: 'textBlock', text: 'not json at all' })

    const extractor = new ModelExtractor({ model: model as unknown as Model })
    const entries = await extractor.extract([userTurn('x')])

    expect(entries).toEqual([])
  })

  it('drops entries without a string content and empty strings', async () => {
    const model = new MockMessageModel()
    model.addTurn({ type: 'textBlock', text: '[{"content": "keep"}, {"content": ""}, {"foo": "bar"}, "loose"]' })

    const extractor = new ModelExtractor({ model: model as unknown as Model })
    const entries = await extractor.extract([userTurn('x')])

    expect(entries).toEqual([{ content: 'keep' }])
  })

  it('returns [] for an empty message batch without calling the model', async () => {
    const model = new MockMessageModel()
    const extractor = new ModelExtractor({ model: model as unknown as Model })

    const entries = await extractor.extract([])

    expect(entries).toEqual([])
    expect(model.callCount).toBe(0)
  })

  it('falls back to the default model from context when none configured', async () => {
    const model = new MockMessageModel()
    model.addTurn({ type: 'textBlock', text: '[{"content": "fact"}]' })

    const extractor = new ModelExtractor()
    const entries = await extractor.extract([userTurn('x')], { defaultModel: model as unknown as Model })

    expect(entries).toEqual([{ content: 'fact' }])
  })

  it('throws when no model is configured and no default is provided', async () => {
    const extractor = new ModelExtractor()
    await expect(extractor.extract([userTurn('x')])).rejects.toThrow('no model configured')
  })

  it('wraps the model call in a model-invoke span when a tracer is supplied', async () => {
    const model = new MockMessageModel()
    model.addTurn({ type: 'textBlock', text: '[{"content": "fact"}]' })
    const startSpy = vi.spyOn(Tracer.prototype, 'startModelInvokeSpan')
    const endSpy = vi.spyOn(Tracer.prototype, 'endModelInvokeSpan')

    const extractor = new ModelExtractor({ model: model as unknown as Model })
    await extractor.extract([userTurn('x')], { tracer: new Tracer() })

    expect(startSpy).toHaveBeenCalledTimes(1)
    expect(endSpy).toHaveBeenCalledTimes(1)
    expect(endSpy.mock.calls[0]![1]?.error).toBeUndefined()
    expect(endSpy.mock.calls[0]![1]?.output).toBeDefined()

    startSpy.mockRestore()
    endSpy.mockRestore()
  })

  it('extracts without a tracer in context (standalone use)', async () => {
    const model = new MockMessageModel()
    model.addTurn({ type: 'textBlock', text: '[{"content": "fact"}]' })

    const extractor = new ModelExtractor({ model: model as unknown as Model })
    // No context at all -> the optional span calls no-op.
    const entries = await extractor.extract([userTurn('x')])

    expect(entries).toEqual([{ content: 'fact' }])
  })

  it('ends the model-invoke span with an error when the model throws', async () => {
    const failing = {
      streamAggregated: () => {
        throw new Error('model down')
      },
    }
    const endSpy = vi.spyOn(Tracer.prototype, 'endModelInvokeSpan')

    const extractor = new ModelExtractor({ model: failing as unknown as Model })
    await expect(extractor.extract([userTurn('x')], { tracer: new Tracer() })).rejects.toThrow('model down')

    expect(endSpy).toHaveBeenCalledTimes(1)
    expect(endSpy.mock.calls[0]![1]?.error).toBeInstanceOf(Error)

    endSpy.mockRestore()
  })
})
